BEGIN;
CREATE FUNCTION pg_temp.reward_change(a uuid,s uuid,action text,d jsonb,k text) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.reward_admin_mutate(a,s,action,d,md5(k)||md5(k),md5(action||d::text)||md5(action||d::text),gen_random_uuid()) $$;
DO $$ DECLARE a uuid;s uuid;ordinary uuid;os uuid;m uuid;m2 uuid;r jsonb;r2 jsonb;rule uuid;activity uuid;cred uuid;entry uuid;perk uuid;sid uuid;own jsonb;claim uuid;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('rewards-super@example.test','fictional','super_admin',true) RETURNING id INTO a;
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('rewards-admin@example.test','fictional','admin',true) RETURNING id INTO ordinary;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(a,repeat('12',32)) RETURNING id INTO s;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(ordinary,repeat('13',32)) RETURNING id INTO os;
 INSERT INTO public.members(name,email) VALUES('Fictional Rewards Member','rewards-member@gatech.edu') RETURNING id INTO m;
 INSERT INTO public.members(name,email) VALUES('Fictional Other Member','rewards-other@gatech.edu') RETURNING id INTO m2;
 BEGIN PERFORM pg_temp.reward_change(ordinary,os,'adjust',jsonb_build_object('memberId',m,'points',50,'reason','Forbidden adjustment'),'noadmin');RAISE EXCEPTION 'Ordinary admin adjusted points';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.reward_admin_read(ordinary,os,'',1,m);RAISE EXCEPTION 'Ordinary admin read private rewards';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.reward_admin_read(a,s,'',1,m);IF r#>>'{selectedMember,id}'<>m::text OR(r->>'total')::int<>2 THEN RAISE EXCEPTION 'Super admin member inventory failed';END IF;
 r:=pg_temp.reward_change(a,s,'rule','{"title":"Fictional attendance","points":15,"active":true}','rule');rule:=(r->>'id')::uuid;
 r:=pg_temp.reward_change(a,s,'activity',jsonb_build_object('title','Fictional event','ruleId',rule,'opensAt',now()-interval '1 hour','closesAt',now()+interval '1 hour'),'activity');activity:=(r->>'id')::uuid;
 r:=pg_temp.reward_change(a,s,'credential',jsonb_build_object('memberId',m,'kind','card','label','Fictional card','tokenHash',repeat('14',32),'encryptedToken','fictional-encrypted-token'),'card');cred:=(r->>'id')::uuid;
 IF public.reward_resolve(a,s,repeat('14',32))->>'id'<>m::text THEN RAISE EXCEPTION 'Card resolved wrong member';END IF;
 r:=pg_temp.reward_change(a,s,'award',jsonb_build_object('memberId',m,'activityId',activity,'credentialId',cred),'award');entry:=(r->>'id')::uuid;
 r2:=pg_temp.reward_change(a,s,'award',jsonb_build_object('memberId',m,'activityId',activity,'credentialId',cred),'award');IF r<>r2 OR gdg_security.reward_balance(m)<>15 THEN RAISE EXCEPTION 'Retry double awarded';END IF;
 BEGIN PERFORM pg_temp.reward_change(a,s,'award',jsonb_build_object('memberId',m,'activityId',activity),'another-tap');RAISE EXCEPTION 'Second tap double awarded';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM pg_temp.reward_change(a,s,'adjust',jsonb_build_object('memberId',m,'points',10,'reason','Changed intent'),'award');RAISE EXCEPTION 'Reused key changed intent';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 BEGIN UPDATE public.reward_ledger SET points=900 WHERE id=entry;RAISE EXCEPTION 'Ledger edited';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM pg_temp.reward_change(a,s,'adjust',jsonb_build_object('memberId',m,'points',-16,'reason','Negative balance'),'negative');RAISE EXCEPTION 'Negative balance allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 IF (public.reward_public_board(1)->>'total')::int<>0 THEN RAISE EXCEPTION 'Private directory leaked to leaderboard';END IF;
 sid:=public.reward_open_session('rewards-member@gatech.edu','custom:gatech:fictional-subject',repeat('15',32),repeat('16',32));own:=public.reward_member_read(repeat('15',32));
 IF own->>'id'<>m::text THEN RAISE EXCEPTION 'Member session resolved wrong person';END IF;
 BEGIN PERFORM public.reward_open_session('rewards-member@gatech.edu','custom:gatech:different-subject',repeat('17',32),repeat('18',32));RAISE EXCEPTION 'Subject rebound';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.reward_open_session('unknown@gatech.edu','custom:gatech:unknown',repeat('17',32),repeat('18',32));RAISE EXCEPTION 'Unknown directory person joined';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.reward_member_mutate(repeat('15',32),repeat('16',32),'profile','{"alias":"Fictional Builder","public":true}',repeat('19',32),repeat('20',32));
 r:=public.reward_public_board(1);IF(r->>'total')::int<>1 OR r#>>'{items,0,alias}'<>'Fictional Builder' OR r#>>'{items,0,points}'<>'15' OR r::text LIKE '%rewards-member@%' OR r::text LIKE '%'||m::text||'%' THEN RAISE EXCEPTION 'Public board scope/PII failure';END IF;
 r:=pg_temp.reward_change(a,s,'perk','{"title":"Fictional merch","description":"Fictional stock for database test","threshold":10,"inventory":1,"active":true}','perk');perk:=(r->>'id')::uuid;
 r:=public.reward_member_mutate(repeat('15',32),repeat('16',32),'claim',jsonb_build_object('perkId',perk),repeat('21',32),repeat('22',32));claim:=(r->>'id')::uuid;
 r2:=public.reward_member_mutate(repeat('15',32),repeat('16',32),'claim',jsonb_build_object('perkId',perk),repeat('21',32),repeat('22',32));IF r<>r2 THEN RAISE EXCEPTION 'Claim retry changed';END IF;
 BEGIN PERFORM public.reward_member_mutate(repeat('15',32),repeat('30',32),'profile','{"alias":"Forged","public":true}',repeat('31',32),repeat('32',32));RAISE EXCEPTION 'Member CSRF bypass';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM pg_temp.reward_change(a,s,'claim_status',jsonb_build_object('id',claim,'revision',1,'status','approved'),'approve');
 PERFORM pg_temp.reward_change(a,s,'claim_status',jsonb_build_object('id',claim,'revision',2,'status','fulfilled'),'fulfill');
 BEGIN PERFORM pg_temp.reward_change(a,s,'claim_status',jsonb_build_object('id',claim,'revision',3,'status','approved'),'backwards');RAISE EXCEPTION 'Fulfilment went backwards';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 PERFORM pg_temp.reward_change(a,s,'reverse',jsonb_build_object('id',entry,'reason','Fictional reversal'),'reverse');IF gdg_security.reward_balance(m)<>0 THEN RAISE EXCEPTION 'Reversal did not compensate';END IF;
 BEGIN PERFORM pg_temp.reward_change(a,s,'reverse',jsonb_build_object('id',entry,'reason','Duplicate reversal'),'reverse-again');RAISE EXCEPTION 'Double reversal';EXCEPTION WHEN unique_violation THEN NULL;WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 PERFORM pg_temp.reward_change(a,s,'revoke',jsonb_build_object('id',cred),'revoke');
 BEGIN PERFORM public.reward_resolve(a,s,repeat('14',32));RAISE EXCEPTION 'Revoked card resolved';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 r:=pg_temp.reward_change(a,s,'credential',jsonb_build_object('memberId',m,'kind','card','label','Replacement','tokenHash',repeat('23',32),'encryptedToken','fictional-replacement'),'replacement');
 IF public.reward_resolve(a,s,repeat('23',32))->>'id'<>m::text THEN RAISE EXCEPTION 'Replacement lost member identity';END IF;
 BEGIN UPDATE public.members SET merged_into_id=m2 WHERE id=m;RAISE EXCEPTION 'Rewards merge silently discarded history';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'REWARD_MERGE_REVIEW_REQUIRED' THEN RAISE;END IF;END;
 UPDATE public.members SET is_active=false WHERE id=m;
 BEGIN PERFORM public.reward_member_read(repeat('15',32));RAISE EXCEPTION 'Inactive member session survived';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.reward_resolve(a,s,repeat('23',32));RAISE EXCEPTION 'Inactive member card survived';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 IF(public.reward_public_board(1)->>'total')::int<>0 THEN RAISE EXCEPTION 'Inactive public profile survived';END IF;
 UPDATE public.admin_sessions SET revoked_at=now() WHERE id=s;
 BEGIN PERFORM pg_temp.reward_change(a,s,'adjust',jsonb_build_object('memberId',m2,'points',1,'reason','Revoked session'),'revoked');RAISE EXCEPTION 'Revoked admin wrote points';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_table_privilege('anon','public.reward_ledger','SELECT') OR has_table_privilege('authenticated','public.reward_credentials','SELECT') OR has_function_privilege('authenticated','public.reward_public_board(integer)','EXECUTE') OR has_function_privilege('gdg_realtime','public.reward_open_session(text,text,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Rewards browser privileges leaked';END IF;
END $$;
ROLLBACK;
